def html_bytes(): return gzip.decompress(base64.b64decode(HTML_GZIP_B64))
def data_url_bytes(value):
    if not value or ',' not in value:return None
    try:return base64.b64decode(value.split(',',1)[1])
    except Exception:return None

def p(text='',bold=False,size=20,color=None,align=None,break_after=False):
    props=[]
    if bold:props.append('<w:b/>')
    if size:props.append(f'<w:sz w:val="{size}"/><w:szCs w:val="{size}"/>')
    if color:props.append(f'<w:color w:val="{color}"/>')
    ppr=f'<w:pPr><w:jc w:val="{align}"/></w:pPr>' if align else ''
    br='<w:br w:type="page"/>' if break_after else ''
    return f'<w:p>{ppr}<w:r><w:rPr>{"".join(props)}</w:rPr><w:t xml:space="preserve">{escape(str(text))}</w:t>{br}</w:r></w:p>'

def table(rows):
    out=['<w:tbl><w:tblPr><w:tblW w:w="0" w:type="auto"/><w:tblBorders><w:top w:val="single" w:sz="4" w:color="AFC5DD"/><w:left w:val="single" w:sz="4" w:color="AFC5DD"/><w:bottom w:val="single" w:sz="4" w:color="AFC5DD"/><w:right w:val="single" w:sz="4" w:color="AFC5DD"/><w:insideH w:val="single" w:sz="4" w:color="D5E0EA"/><w:insideV w:val="single" w:sz="4" w:color="D5E0EA"/></w:tblBorders></w:tblPr>']
    for row in rows:
        cells=list(row)+['']*(3-len(row));out.append('<w:tr>')
        for i,c in enumerate(cells[:3]):out.append(f'<w:tc><w:tcPr><w:tcW w:w="{4000 if i==0 else 2500}" w:type="dxa"/></w:tcPr>{p(c,bold=(i==0),size=18)}</w:tc>')
        out.append('</w:tr>')
    out.append('</w:tbl>');return ''.join(out)

def image_para(rid,name,cx,cy):
    return f"""<w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="{cx}" cy="{cy}"/><wp:docPr id="1" name="{escape(name)}"/><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic><pic:nvPicPr><pic:cNvPr id="0" name="{escape(name)}"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="{rid}"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="{cx}" cy="{cy}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>"""

def build_docx(payload,letterhead):
    imgs=[];rels=[];rid=1
    for key,ext in [('logo','png'),('coil','png'),('psych','png'),('coating','jpg')]:
        b=data_url_bytes(payload.get('images',{}).get(key))
        if b:
            imgs.append((key,ext,b,rid));rels.append(f'<Relationship Id="rId{rid}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/{key}.{ext}"/>');rid+=1
    ridmap={k:f'rId{r}' for k,e,b,r in imgs}
    body=[]
    body.append(p(payload.get('title','CST COIL CAD – STEAM COIL SELECTION'),True,32,'003B7A','center'))
    body.append(p(payload.get('subtitle',''),True,22,'E87800','center'))
    body.append(p('PROJECT / SELECTION INFORMATION',True,22,'003B7A'))
    body.append(table([[k,v,''] for k,v in payload.get('project',{}).items()]))
    sections=payload.get('sections',[])
    for i,sec in enumerate(sections):
        if i in (3,7,8):body.append(p('',break_after=True))
        body.append(p(sec.get('title',''),True,22,'A52626'))
        body.append(table(sec.get('rows',[])))
        if i==6 and 'psych' in ridmap:
            body.append(p('',break_after=True));body.append(p('PSYCHROMETRIC HEATING PROCESS',True,24,'003B7A','center'));body.append(image_para(ridmap['psych'],'Psychrometric Chart',6200000,3650000))
        if i==7 and 'coil' in ridmap:
            body.append(p('',break_after=True));body.append(p('SELECTED COIL MATERIAL & COATING VISUAL',True,24,'003B7A','center'));body.append(image_para(ridmap['coil'],'Coil Visual',4600000,5700000))
        if i==8 and 'coating' in ridmap:
            body.append(p(payload.get('coatingName','Protective Coating'),True,22,'003B7A','center'));body.append(image_para(ridmap['coating'],'Coating Photo',5000000,3600000))
    sect='<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="900" w:right="850" w:bottom="850" w:left="850" w:header="450" w:footer="450" w:gutter="0"/>'
    if letterhead:sect+='<w:headerReference w:type="default" r:id="rIdHeader"/><w:footerReference w:type="default" r:id="rIdFooter"/>'
    sect+='</w:sectPr>';body.append(sect)
    document=f"""<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><w:body>{''.join(body)}</w:body></w:document>"""
    docrels=list(rels)
    if letterhead:
        docrels+=['<Relationship Id="rIdHeader" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/header" Target="header1.xml"/>','<Relationship Id="rIdFooter" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" Target="footer1.xml"/>']
    relxml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+''.join(docrels)+'</Relationships>'
    header='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:hdr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'+p('CST COIL CAD™  |  STEAM COIL SELECTION',True,22,'003B7A','center')+'</w:hdr>'
    footer='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:ftr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'+p('CST EnviroTech • Preliminary Engineering Selection',False,16,'48647F','center')+'</w:ftr>'
    ct="""<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Default Extension="jpg" ContentType="image/jpeg"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>"""+('<Override PartName="/word/header1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml"/><Override PartName="/word/footer1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml"/>' if letterhead else '')+'</Types>'
    rootrels="""<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>"""
    bio=io.BytesIO()
    with zipfile.ZipFile(bio,'w',zipfile.ZIP_DEFLATED) as z:
        z.writestr('[Content_Types].xml',ct);z.writestr('_rels/.rels',rootrels);z.writestr('word/document.xml',document);z.writestr('word/_rels/document.xml.rels',relxml)
        if letterhead:z.writestr('word/header1.xml',header);z.writestr('word/footer1.xml',footer)
        for key,ext,b,r in imgs:z.writestr(f'word/media/{key}.{ext}',b)
    return bio.getvalue()

class Handler(http.server.BaseHTTPRequestHandler):
    def log_message(self,*args):pass
    def send_bytes(self,data,ctype,status=200,extra=None):
        self.send_response(status);self.send_header('Content-Type',ctype);self.send_header('Content-Length',str(len(data)))
        for k,v in (extra or {}).items():self.send_header(k,v)
        self.end_headers();self.wfile.write(data)
    def do_GET(self):
        if self.path in ('/','/index.html'):self.send_bytes(html_bytes(),'text/html; charset=utf-8')
        elif self.path=='/health':self.send_bytes(b'OK','text/plain')
        else:self.send_bytes(b'Not found','text/plain',404)
    def do_POST(self):
        path=urlparse(self.path)
        if path.path=='/shutdown':
            self.send_bytes(b'OK','text/plain');threading.Thread(target=self.server.shutdown,daemon=True).start();return
        if path.path=='/export-docx':
            try:
                length=int(self.headers.get('Content-Length','0'));payload=json.loads(self.rfile.read(length) or b'{}');letter=parse_qs(path.query).get('letterhead',['0'])[0]=='1';data=build_docx(payload,letter);name='CST_Steam_Coil_Report.docx';self.send_bytes(data,'application/vnd.openxmlformats-officedocument.wordprocessingml.document',extra={'Content-Disposition':f'attachment; filename="{name}"'})
            except Exception as e:self.send_bytes(str(e).encode(),'text/plain',500)
            return
        self.send_bytes(b'Not found','text/plain',404)

def free_port(preferred):
    for p in [preferred,0]:
        s=socket.socket();s.bind(('127.0.0.1',p));port=s.getsockname()[1];s.close();return port

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--port',type=int,default=8765);ap.add_argument('--no-browser',action='store_true');ap.add_argument('--extract-html',action='store_true');args=ap.parse_args()
    if args.extract_html:
        out=Path(__file__).with_suffix('.html');out.write_bytes(html_bytes());print(out);return
    port=free_port(args.port);server=http.server.ThreadingHTTPServer(('127.0.0.1',port),Handler);url=f'http://127.0.0.1:{port}/';print(f'{APP_NAME} running at {url}')
    if not args.no_browser:threading.Timer(.7,lambda:webbrowser.open(url)).start()
    try:server.serve_forever()
    except KeyboardInterrupt:pass
    finally:server.server_close()
if __name__=='__main__':main()
